    """Calculate Dice coefficient between two strings based on bigram overlap."""
    if not s1 and not s2:
        return 1.0
    def _bigrams(s: str):
        return [s[i : i + 2] for i in range(len(s) - 1)]
    bigrams1 = _bigrams(s1)
    bigrams2 = _bigrams(s2)
    if not bigrams1 and not bigrams2:
        return 1.0

